    function toast(t,err=false){const e=document.createElement('div');e.className='toast'+(err?' error':'');e.textContent=t;$('#toastRegion').append(e);setTimeout(()=>e.remove(),3200)}
function pill(s){const c=({OBSERVED:'mint',REFUTED_FOR_RUN:'red',POSSIBLE:'amber',UNKNOWN:'purple',SUCCESS:'mint',PASS:'mint',WARNING:'amber',FAILED:'red',FAIL:'red'})[s]||'gray';return '<span class="pill '+c+'">'+esc(s)+'</span>'}
function head(t,d,act=''){return '<div class="page-heading"><div><h1>'+t+'</h1><p>'+d+'</p></div><div class="heading-actions">'+act+'</div></div>'}
function panel(t,body,sub='',act=''){return '<section class="panel"><div class="panel-head"><div><h2>'+t+'</h2>'+(sub?'<p>'+sub+'</p>':'')+'</div>'+act+'</div>'+body+'</section>'}
function table(h,rows,empty='No matching records'){return '<div class="table-wrap"><table><thead><tr>'+h.map(x=>'<th'+(/^(Rows|Columns|Quality|Score|Assets|Events|Duration|Hops)$/.test(x)?' class="num"':'')+'>'+x+'</th>').join('')+'</tr></thead><tbody>'+(rows.length?rows.join(''):'<tr><td colspan="'+h.length+'"><div class="empty-state"><img src="/empty-state.png" alt="" aria-hidden="true" style="max-width:140px; margin-bottom:20px; opacity:0.85;"><strong>'+empty+'</strong>Try adjusting your filters.</div></td></tr>')+'</tbody></table></div>'}
function card(label,val,icon,foot,lead){return '<div class="stat-card'+(lead?' lead':'')+'"><div class="stat-top"><span>'+label+'</span></div><div class="stat-value">'+val+'</div><div class="stat-foot">'+foot+'</div></div>'}
function findingText(){const r=V.find(e=>e.state==='REFUTED_FOR_RUN'),run=r&&R.find(x=>x.id===r.run),ob=V.filter(e=>e.state==='OBSERVED').length;if(!V.length)return 'No evidence records yet.';return r?'<strong>'+esc(r.source)+' → '+esc(r.target)+'</strong> is refuted for '+esc(r.run)+(run&&run.status==='FAILED'?', a failed run':'')+'. '+ob+' of '+V.length+' dependencies are observed.':ob+' of '+V.length+' dependencies are observed. None is refuted for a run.'}
function evidenceStrip(){const c={OBSERVED:0,POSSIBLE:0,REFUTED_FOR_RUN:0,UNKNOWN:0};V.forEach(e=>{if(c[e.state]!==undefined)c[e.state]++});const t=V.length;if(!t)return '<div class="evidence-strip" role="img" aria-label="No evidence records"><i style="flex:1"></i></div>';const cls={OBSERVED:'s-observed',POSSIBLE:'s-possible',REFUTED_FOR_RUN:'s-refuted',UNKNOWN:'s-unknown'};return '<div class="evidence-strip" role="img" aria-label="'+c.OBSERVED+' observed, '+c.POSSIBLE+' possible, '+c.REFUTED_FOR_RUN+' refuted for a run, '+c.UNKNOWN+' unknown">'+Object.keys(c).filter(k=>c[k]).map(k=>'<i class="'+cls[k]+'" style="flex:'+c[k]+'"></i>').join('')+'</div>'}
