$('#globalSearchButton').addEventListener('click',()=>{trackUX('kairos_global_search_opened',{view:S.view,data_mode:S.dataMode});modal('Search workspace','<div class="field"><label for="globalSearchInput">Search assets, schemas, owners, evidence, runs and quality checks</label><input id="globalSearchInput" class="field-input" placeholder="Try an asset name, owner, run ID or check…"></div><p class="small-note">Searches the currently selected '+(S.dataMode==='demo'?'demo workspace':'persisted catalog')+'. Use Ctrl+K or ⌘K to open search.</p><div id="globalResults" class="reasoning-list" style="margin-top:12px" aria-live="polite"><div class="empty-state"><strong>Search your workspace</strong>Start typing to find assets, lineage evidence, pipeline runs or quality checks.</div></div>');const inp=$('#globalSearchInput');inp.focus();inp.addEventListener('input',()=>{const q=inp.value.trim().toLowerCase();if(!q){$('#globalResults').innerHTML='<div class="empty-state"><strong>Search your workspace</strong>Enter a name, owner, schema, run ID or quality check.</div>';return}const found=[...A.filter(a=>(a.path+' '+a.name+' '+a.schema+' '+a.owner+' '+a.type+' '+(a.description||'')).toLowerCase().includes(q)).slice(0,5).map(a=>({label:a.path||a.name,detail:(a.owner||'Unassigned')+' · '+(a.type||a.kind||'Asset'),type:'Asset',id:a.id,view:'assets'})),...V.filter(a=>(a.id+' '+a.source+' '+a.target+' '+a.state+' '+a.type+' '+a.rule+' '+a.why).toLowerCase().includes(q)).slice(0,4).map(a=>({label:a.id+' · '+a.source+' → '+a.target,detail:a.state+' · '+a.type,type:'Evidence',id:a.id,view:'evidence'})),...R.filter(a=>(a.id+' '+a.name+' '+a.status+' '+a.env).toLowerCase().includes(q)).slice(0,3).map(a=>({label:a.id+' · '+a.name,detail:a.status+' · '+a.env,type:'Run',id:a.id,view:'runs'})),...Q.filter(a=>(a.name+' '+a.asset+' '+a.type+' '+a.status).toLowerCase().includes(q)).slice(0,3).map(a=>({label:a.name,detail:a.asset+' · '+a.status,type:'Quality',id:'',view:'quality'}))];trackUX('kairos_search_results',{view:S.view,result_count:found.length});$('#globalResults').innerHTML=found.map(x=>'<button class="reasoning-item" style="width:100%;text-align:left" data-view="'+x.view+'" '+(x.id?'data-id="'+esc(x.id)+'"':'')+'><div class="reason-head"><strong>'+esc(x.label)+'</strong>'+pill(x.type)+'</div><p>'+esc(x.detail||'')+'</p></button>').join('')||'<div class="empty-state"><strong>No matches found</strong>Try a shorter term or search by schema, owner, run ID or check name.</div>'})});
