function setSidebarCollapsed(collapsed){const side=$('#sidebar');side.classList.toggle('collapsed',collapsed);side.classList.remove('open');localStorage.setItem('kairos_sidebarCollapsed',String(collapsed));const toggle=$('#sidebarToggleBtn');if(toggle){toggle.setAttribute('aria-expanded',String(!collapsed));toggle.setAttribute('aria-label',collapsed?'Expand sidebar':'Collapse sidebar');toggle.title=collapsed?'Expand sidebar':'Collapse sidebar'}}function openMobileSidebar(){const side=$('#sidebar');side.classList.remove('collapsed');side.classList.add('open');localStorage.setItem('kairos_sidebarCollapsed','false')}$('#openNav').addEventListener('click',()=>{if(window.matchMedia('(max-width: 900px)').matches){const side=$('#sidebar');if(side.classList.contains('open')){side.classList.remove('open');side.classList.add('collapsed');localStorage.setItem('kairos_sidebarCollapsed','true')}else openMobileSidebar()}else setSidebarCollapsed(!$('#sidebar').classList.contains('collapsed'))});$('#closeNav').addEventListener('click',()=>setSidebarCollapsed(true));$('#sidebarToggleBtn')?.addEventListener('click',()=>setSidebarCollapsed(!$('#sidebar').classList.contains('collapsed')));document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modalBackdrop').hidden=true;if(window.innerWidth<=768)$('#sidebar').classList.add('collapsed')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearchButton').click()}});/* Phase 2: Toast swipe-to-dismiss */
function enableToastSwipe(){$$('#toastRegion .toast').forEach(t=>{let sx=0,sw=false;t.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button)return;sx=e.clientX;sw=true;t.classList.add('active')},0);t.addEventListener('pointermove',e=>{if(!sw)return;if(e.clientX-sx>60){t.classList.add('swipe-out');sw=false;setTimeout(()=>t.remove(),250)}},0);t.addEventListener('pointerup',()=>{t.classList.remove('active');sw=false},0)})};setInterval(enableToastSwipe,100);const origToast=toast;toast=function(msg,err){origToast(msg,err);enableToastSwipe()};/* Phase 2: Graph tooltips */
function attachGraphTooltips(){$$('[data-node]').forEach(n=>{const id=n.getAttribute('data-id'),a=A.find(x=>x.id===id);if(!a)return;n.addEventListener('mouseenter',()=>{if(n._t)return;const t=document.createElement('div');t.className='graph-tooltip';t.textContent=a.name+' ('+a.rows+' rows)';n.parentElement?.appendChild(t);n._t=t;setTimeout(()=>t.classList.add('visible'),10)});n.addEventListener('mouseleave',()=>{if(n._t){n._t.classList.remove('visible');setTimeout(()=>{n._t?.remove();n._t=null},150)}})})};setInterval(attachGraphTooltips,200);/* Phase 2: Sidebar state on load */
if(localStorage.getItem('kairos_sidebarCollapsed')==='true')$('#sidebar').classList.add('collapsed');/* Phase 2: Mobile nav auto-close */
if(window.innerWidth<=768){$$('.nav-item').forEach(item=>{item.addEventListener('click',()=>{setTimeout(()=>{$('#sidebar').classList.add('collapsed');localStorage.setItem('kairos_sidebarCollapsed','true')},100)})})};
